(() => {
  'use strict';
  const D=structuredClone(window.CAMPAIGN_DATA), M={...window.CAMPAIGN_MEDIA,art:[...window.CAMPAIGN_MEDIA.art]}, W=window.GHOST_WAVEFORMS||{};
  const U=window.applyCodexUpgrades(D,M);
  const $=id=>document.getElementById(id);
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const plain=s=>{const el=document.createElement('div');el.innerHTML=s||'';return el.textContent||'';};
  const short=(s,n=135)=>{const t=plain(s);return t.length>n?t.slice(0,n).trim()+'…':t;};
  const path=(kind,id)=>'#'+kind+'/'+encodeURIComponent(id);
  const asset=n=>M.art.find(a=>a.id===String(n).padStart(3,'0')&&!a.video&&!a.source.includes('_alts'))?.src||'';
  const artItem=n=>M.art.find(a=>a.id===String(n).padStart(3,'0')&&!a.video&&!a.source.includes('_alts'));
  const worlds=[...D.LOCATIONS,D.VOID,...D.PLACE_ENTRIES];
  const world=id=>worlds.find(l=>l.id===id);
  const allContacts=D.LOCATIONS.flatMap(l=>(l.contacts||[]).map(c=>({...c,location:c.location||{id:l.id,label:l.name}})));
  const contacts=allContacts.filter((p,i,a)=>a.findIndex(x=>x.name===p.name)===i);
  const allPeople=[...D.POI,...contacts].filter((p,i,a)=>a.findIndex(x=>x.name===p.name)===i);
  const recordings=[...M.recordings].sort((a,b)=>b.session-a.session||M.recordings.indexOf(a)-M.recordings.indexOf(b));
  const navItems=[['bridge','Bridge','⌂'],['previously','Previously on…','▤'],['relationships','Connections','◎'],['map','Star map','✧'],['journal','Flight journal','▤'],['crew','The crew','♙'],['directory','Directory','◎'],['lore','The codex','◇'],['ghost','Ghost archive','◉'],['art','Art library','▧'],['threads','Open threads','⌘']];
  const iconPaths={bridge:'M3 11 12 3l9 8M5 9v11h14V9M9 20v-7h6v7',map:'M12 2v20M2 12h20M5 5l14 14M19 5 5 19M8 8h8v8H8z',journal:'M6 3h14v18H6M3 3v18M10 8h6M10 12h6M10 16h4',crew:'M16 8a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 21v-3a5 5 0 0 1 5-5h6a5 5 0 0 1 5 5v3',directory:'M20 12a8 8 0 1 1-16 0 8 8 0 0 1 16 0ZM15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0M12 1v3M12 20v3M1 12h3M20 12h3',lore:'m12 2 10 10-10 10L2 12 12 2ZM7 12h10M12 7v10',ghost:'M3 9v6M7 5v14M11 2v20M15 6v12M19 4v16M23 9v6',art:'M3 3h18v18H3V3ZM3 17l6-6 5 5 3-3 4 4M17 7h.01',threads:'M8 3v18M16 3v18M3 8h18M3 16h18'};
  const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[name]||iconPaths.lore}"/></svg>`;
  const safeRead=(key,fallback)=>{try{return localStorage.getItem(key)??fallback;}catch{return fallback;}};
  const safeWrite=(key,value)=>{try{localStorage.setItem(key,value);}catch{}};
  const reduced=matchMedia('(prefers-reduced-motion: reduce)');
  const state={route:'bridge',sub:'',dm:false,motion:!reduced.matches&&safeRead('shattering-motion','on')!=='off',galaxy:null,playingId:null,queue:recordings.map(r=>r.id),ghostFilter:'all',ghostSession:'all',artFilter:'all',artSearch:'',artLimit:48,dirFilter:'all',dirSearch:'',dirCrew:'all',crewFilter:'all',journalCrew:'c2',threadCrew:'c2',threadFilter:'all',searchIndex:0,searchResults:[],lastFocus:null};
  const tag=(text,cls='')=>`<span class="tag ${cls}">${esc(text)}</span>`;
  const crewLabel=c=>c==='c1'?'The Codex Crew':c==='both'?'Both crews':'H.O.C.2.A';
  const rimLabel=r=>({inner:'Inner Rim',mid:'Midreach',outer:'Outer Rim',station:'Station',unknown:'Uncharted',void:'The Maw'}[r]||'Landmark');
  const stanceClass=s=>['allied','friendly','eidolon'].includes(s)?'cyan':['hostile','deceased','crit','hot'].includes(s)?'red':s==='captive'?'gold':'';
  const image=(src,alt,cls='',eager=false)=>src?`<img src="${esc(src)}" alt="${esc(alt)}" ${cls?`class="${cls}"`:''} ${eager?'fetchpriority="high"':'loading="lazy"'} decoding="async">`:'';
  const pageHead=(eyebrow,title,description='',aside='')=>`<div class="page-head"><div><p class="eyebrow">${esc(eyebrow)}</p><h1>${esc(title)}</h1>${description?`<p>${esc(description)}</p>`:''}</div>${aside?`<span class="head-aside">${esc(aside)}</span>`:''}</div>`;
  const section=(title,link='',text='Explore all ↗')=>`<div class="section-heading"><h2>${esc(title)}</h2>${link?`<a href="${link}">${esc(text)}</a>`:''}</div>`;
  const locationLink=loc=>loc?.id?`<a href="${path('world',loc.id)}">${esc(loc.label||world(loc.id)?.name||loc.id)} ↗</a>`:esc(loc?.label||'Location unrecorded');
  const dmNote=text=>state.dm&&text?`<div class="panel dm-note"><p class="eyebrow">Dungeon Master notes</p><div class="prose">${text}</div></div>`:'';
  const contraband=(label='Personal effects')=>`<details class="disclosure"><summary>${esc(label)}</summary><button class="stashed-book" data-book>${image('media/art/blue-harvest.webp','A well-travelled paperback')}<span>An unexpectedly well-read paperback.<br><small>A note in the margin says: “Borrowed. Probably.”</small></span></button></details>`;
  const tuckedBook=(variant='')=>`<button class="paperback-stash ${variant}" data-book aria-label="Inspect a tucked-away paperback" title="Somebody left this here.">${image('media/art/blue-harvest.webp','')}</button>`;
  const tabs=(items,key,value)=>`<div class="tabs" aria-label="Filter">${items.map(([id,label])=>`<button class="tab${id===value?' active':''}" data-filter="${key}" data-value="${id}" aria-pressed="${id===value}">${esc(label)}</button>`).join('')}</div>`;
  const duration=id=>formatTime(W[id]?.duration||0);
  function formatTime(sec){sec=Number.isFinite(sec)?Math.floor(sec):0;return `${Math.floor(sec/60)}:${String(sec%60).padStart(2,'0')}`;}
  function wave(id){const peaks=W[id]?.peaks||Array(100).fill(.12);return `<button class="waveform" data-wave="${id}" aria-label="Seek within ${esc(M.recordings.find(r=>r.id===id)?.title)}"><svg viewBox="0 0 ${peaks.length*3} 40" preserveAspectRatio="none" aria-hidden="true">${peaks.map((p,i)=>`<rect x="${i*3}" y="${20-Math.max(2,p*18)}" width="1.6" height="${Math.max(4,p*36)}" rx=".6" data-peak="${i/peaks.length}"/>`).join('')}</svg></button>`;}
  function recordingCard(r,compact=false){return `<article class="recording${compact?' compact':''}${r.id===state.playingId?' playing':''}" data-recording="${r.id}"><button class="recording-play" data-play="${r.id}" aria-label="${r.id===state.playingId&&!$('ghostAudio').paused?'Pause':'Play'} ${esc(r.title)}">${r.id===state.playingId&&!$('ghostAudio').paused?'Ⅱ':'▶'}</button><div class="recording-info"><p class="eyebrow">${esc(r.kind==='recap'?'Ghost’s recap':r.kind==='rant'?'Unfiltered rant':'Voice line')} · SESSION ${r.session}</p><h3>${esc(r.title)}</h3><div class="recording-meta"><span>${esc(r.date)}</span><a href="${path('session','S'+r.session)}">Written log ↗</a>${!compact&&r.location?`<a href="${path('world',r.location)}">${esc(world(r.location)?.name||r.setting)} ↗</a>`:''}</div></div>${wave(r.id)}<span class="recording-duration">${duration(r.id)}</span></article>`;}
  function personImage(p){return p.image||M.matches[p.name]||D.CREW.find(c=>c.name===p.name)?.image||'';}
  function personCard(p){const src=personImage(p);return `<a class="entity-card person-card" href="${path('person',p.name)}">${src?image(src,p.name):`<div class="no-art" aria-hidden="true">${esc(p.name.charAt(0))}</div>`}<div class="entity-card-content"><div class="tag-group">${tag(p.stance||p.status||'Contact',stanceClass(p.stance||p.status))}${p.crew?tag(crewLabel(p.crew)):''}</div><h3>${esc(p.name)}</h3><p class="role">${esc(p.class||p.kind||p.faction||'Contact')}</p><p>${esc(short(p.tagline||p.role||p.desc,145))}</p>${p.location?`<div class="card-meta">${esc(p.location.label||world(p.location.id)?.name||'')}</div>`:''}</div></a>`;}
  function worldCard(l){return `<a class="entity-card" href="${path('world',l.id)}">${l.image?image(l.image,l.name):`<div class="no-art" aria-hidden="true">✧</div>`}<div class="entity-card-content"><p class="role">${esc(l.id==='celestial-tunnel'?'Plane of existence':l.parent?world(l.parent)?.name:rimLabel(l.rim))}</p><h3>${esc(l.name)}</h3><p>${esc(short(l.desc,120))}</p>${l.visitedBy?`<div class="card-meta">VISITED · ${esc(crewLabel(l.visitedBy))}</div>`:''}</div></a>`;}
  const F=window.createCodexFeatures({D,M,U,esc,plain,path,image,pageHead,section,tag,personCard,worldCard,recordingCard,sessionCard});
  function bridge(){const last=D.SESSIONS.at(-1);return `<div class="page bridge reveal"><section class="bridge-hero">${image(asset(128),'The illuminated towers of Port Vesper','',true)}<div class="hero-topline"><span class="status-dot"></span> FLIGHT RECORD / ${last.num}</div><div class="hero-content"><p class="eyebrow">H.O.C.2.A · Hogs of Contention</p><h1>Every place leaves<br><em>something behind.</em></h1><p class="hero-description">A fractured galaxy. A crew that refuses to stay dead. Your living record of the worlds, people, and questionable decisions along the way.</p><div class="button-row"><a class="button" href="#map">Explore the star map <span>↗</span></a><a class="button secondary" href="${path('session',last.num)}">Read the latest log</a></div></div><div class="hero-stats"><span><strong>${D.LOCATIONS.length+1}</strong>MAPPED DESTINATIONS</span><span><strong>${D.SESSIONS.length}</strong>FLIGHT LOG ENTRIES</span><span><strong>${M.recordings.length}</strong>GHOST TRANSMISSIONS</span></div><div class="hero-coordinates">CURRENT LOG · STRALEON<span>PORT VESPER / MIDREACH</span></div></section>${section('From the latest transmission','#journal','Open the flight journal ↗')}<div class="story-grid"><a class="story-card" href="${path('session','S15')}">${image(asset(130),'The Dead Pixel bar')}<div class="story-card-content"><p class="eyebrow">SESSION 15 · SEPTEMBER 20, 2026</p><h3>Defectors and Discounts</h3><p>A message for Lor. A defector with a past. Forged coupons and a conspicuously missing hat.</p><span class="card-link">Read the session ↗</span></div></a><a class="story-card" href="#ghost">${image(asset(4),'Aelyn and GHOST-17X')}<div class="story-card-content"><p class="eyebrow">GHOST-17X · OPEN FREQUENCY</p><h3>He has a lot to say.</h3><p>Every recap, rant, and stray voice line. One frequency. Very little restraint.</p><span class="card-link">Open the transmissions ↗</span></div></a><a class="story-card" href="${path('person','Rook')}">${image(asset(134),'Rook, the newest face aboard')}<div class="story-card-content"><p class="eyebrow">CREW UPDATE · BLACK SKY DEFECTOR</p><h3>A new face aboard.</h3><p>Her name is Rook. Ghost has decided otherwise. The rest of the crew knows better.</p><span class="card-link">Meet Rook ↗</span></div></a></div><div class="bridge-bottom"><section class="panel"><p class="eyebrow">Still on the board</p><h3>Unfinished business</h3>${D.HOOKS.filter(h=>h.crew==='c2'&&h.status!=='resolved').slice(0,3).map((h,i)=>`<a class="thread-row" href="#threads"><span class="thread-index">0${i+1}</span><div><h3>${esc(h.title)}</h3><p>${esc(h.location?.label||h.kind)}</p></div>${tag(['high','urgent'].includes(h.urgency)?'HIGH PRIORITY':h.kind,['high','urgent'].includes(h.urgency)?'red':'')}</a>`).join('')}</section><section class="panel quote-panel">${image(asset(4),'')}<p class="eyebrow">Intercepted · Straleon</p><blockquote>“I really wanted a new hat… Dang it.”</blockquote><span class="quote-attr">GHOST / SESSION 15 RECAP</span><div class="button-row" style="margin-top:20px"><button class="button secondary small" data-play="s15">▶ Hear his side of it</button></div></section></div><section class="bridge-map-link"><div><p class="eyebrow">The galaxy is still out there</p><h2>Pick a world. Follow the story.</h2><p>Trace the crew’s flight path, or wander beyond it.</p></div><div class="map-mini"><span class="mini-orbit" aria-hidden="true"></span><a class="button secondary" href="#map">Enter the atlas ↗</a></div></section></div>`;}
  function mapPage(){return `<div class="map-page"><section class="map-shell" aria-label="Interactive campaign star map"><div class="map-stage" id="mapStage"><canvas aria-label="Galaxy orbital chart"></canvas><div class="map-nodes"></div></div><div class="map-hud"><p class="eyebrow"><span class="status-dot"></span> NAVIGATION ARRAY · ONLINE</p><h1>A galaxy in the making.</h1><p>Follow the crew’s path through the fractured worlds of the Shattering.</p><div class="map-tools"><button data-map="cinematic" class="active" aria-pressed="true">Cinematic</button><button data-map="chart" aria-pressed="false">Chart</button><button data-map="filter" aria-pressed="false">Visited worlds</button><button data-map="index">World index ↗</button></div></div><div class="map-legend"><span><i></i> Crew visited</span><span><i></i> Selected world</span><span>— Session flight path</span></div><article id="mapSelection" class="map-selection" hidden></article><div class="map-zoom"><button data-map="in" aria-label="Zoom in">+</button><button data-map="out" aria-label="Zoom out">−</button><button data-map="reset" aria-label="Reset map">⌖</button></div><span class="map-help">Drag to pan · Scroll / pinch to zoom<br>Select a planet to open its dossier</span><span class="map-compass" aria-hidden="true">GALACTIC NORTH</span><div class="flight-log"><div><p class="eyebrow">Flight timeline</p><div class="flight-number" id="flightNumber">SESSION 15</div></div><div class="flight-slider"><input id="flightSlider" type="range" min="0" max="${D.SESSIONS.length-1}" value="${D.SESSIONS.length-1}" aria-label="Select session on the flight timeline"><div class="flight-slider-labels"><span>THE CRASH / S0</span><span>LATEST / S15</span></div></div><div class="flight-info" id="flightInfo"></div></div></section></div>`;}
  function mountMap(){state.galaxy=new window.ShatteringGalaxy($('mapStage'),{locations:[...D.LOCATIONS,D.VOID],sessions:D.SESSIONS,motion:state.motion,onSelect:l=>{const el=$('mapSelection');if(!l){el.hidden=true;return;}el.hidden=false;el.innerHTML=`${l.image?image(l.image,l.name):''}<button class="icon-button map-close" data-map="close" aria-label="Close map selection">×</button><div class="map-selection-body"><p class="eyebrow">${esc(rimLabel(l.rim))}</p><h2>${esc(l.name)}</h2><div class="tag-group">${l.visitedBy?tag('Visited · '+crewLabel(l.visitedBy),'cyan'):tag('Unvisited')}${l.destroyed?tag('Destroyed','red'):''}</div><p>${esc(short(l.desc,155))}</p><a class="button" href="${path('world',l.id)}">Open world dossier ↗</a><button class="button secondary small" data-map="frame" style="margin-top:8px;width:100%">Frame this world ⌖</button></div>`;}});updateFlight(D.SESSIONS.length-1);}
  function updateFlight(index){const s=D.SESSIONS[index];$('flightNumber').textContent=s.num==='S9–10'?'SESSION 9–10':'SESSION '+s.num.slice(1);$('flightInfo').innerHTML=`<small>${esc(s.num)}</small><strong>${esc(s.title)}</strong><a href="${path('session',s.num)}">Read log ↗</a>`;state.galaxy?.setSession(index);$('flightSlider').setAttribute('aria-valuetext',s.num+' · '+s.title+' · '+s.where?.label);}
  function linkedSessions(l){return D.SESSIONS.filter(s=>s.where?.id===l.id||(l.id==='celestial-tunnel'&&['S11','S12'].includes(s.num))||(l.parent&&s.where?.id===l.parent&&plain(s.summary+' '+s.moments.join(' ')).toLowerCase().includes(l.name.split(' /')[0].toLowerCase())));}
  function artForWorld(l){let ids=l.gallery||({straleon:[108,128,138,112,130,153],'gray-haven':[71,72,74,62,69,68],'velthros-moon':[26,27,28,29],velthros:[17,19,20,24],'edgewatch-9':[36,37,52,54],'fellwinter-5':[123],maw:[41]}[l.id]||[]);return ids.map(artItem).filter(Boolean);}
  function artThumbs(items){return `<div class="art-strip">${items.map(a=>`<button class="art-thumb" data-art="${esc(a.src)}" data-caption="${esc(a.title)}">${image(a.src,a.title)}<span>${esc(a.title)}</span></button>`).join('')}</div>`;}
  function ghostAtWorld(l){const lines=M.recordings.filter(r=>r.kind!=='recap'&&r.location===l.id),quote=['straleon','chromehymn'].includes(l.id);return `<section class="panel"><p class="eyebrow">Local frequency</p><h3>Thing Ghost Said while visiting here</h3>${quote?'<div class="prose"><p>“I really wanted a new hat… Dang it.”</p><p><small>Ghost’s Session 15 written recap · shopping in Chromehymn</small></p></div>':''}${lines.map(r=>recordingCard(r,true)).join('')}${!lines.length&&!quote?'<p class="muted" style="font-size:12px">No location-linked Ghost lines archived here yet.</p>':''}<div class="button-row" style="margin-top:18px"><a class="button secondary small" href="#ghost">Open Ghost’s full archive ↗</a></div></section>`;}
  function worldPage(id){const l=world(id);if(!l)return notFound();const parent=world(l.parent),children=D.PLACE_ENTRIES.filter(p=>p.parent===id),localPeople=[...(l.contacts||[]),...D.POI.filter(p=>p.location?.id===id)].filter((p,i,a)=>a.findIndex(x=>x.name===p.name)===i),sessions=linkedSessions(l),art=artForWorld(l),recaps=M.recordings.filter(r=>r.kind==='recap'&&r.location===l.id);return `<div class="page reveal"><div class="breadcrumb"><a href="#map">Star map</a><span>/</span>${parent?`<a href="${path('world',parent.id)}">${esc(parent.name)}</a><span>/</span>`:''}<span>${esc(l.name)}</span></div><section class="dossier-hero">${l.image?image(l.image,l.name,'',true):''}<div class="dossier-hero-content"><p class="eyebrow">${esc(l.id==='celestial-tunnel'?'Divine realm / Plane of existence':parent?parent.name+' / Landmark':rimLabel(l.rim)+' / World dossier')}</p><h1>${esc(l.name)}</h1>${l.subtitle?`<p class="subtitle">${esc(l.subtitle)}</p>`:''}<div class="tag-group">${l.visitedBy?tag('Visited · '+crewLabel(l.visitedBy),'cyan'):''}${l.destroyed?tag('Destroyed','red'):''}${l.court?tag(l.court,'gold'):''}</div></div></section><div class="dossier-layout"><div class="dossier-main"><section class="panel"><p class="eyebrow">Field record</p><div class="prose">${l.desc||'No field record yet.'}</div></section>${l.intel?.length?`<section class="panel"><p class="eyebrow">What we know</p><h3>Field intelligence</h3><ul class="intel-list">${l.intel.map(t=>`<li>${t}</li>`).join('')}</ul></section>`:''}${children.length?section('Places within this world')+`<div class="contact-grid">${children.map(worldCard).join('')}</div>`:''}${localPeople.length?section('Contacts & points of interest')+`<div class="contact-grid">${localPeople.map(personCard).join('')}</div>`:''}${art.length?section('From the field')+artThumbs(art):''}${section('Ghost’s local record')}${ghostAtWorld(l)}${recaps.length?section('Recaps from this part of the journey')+recaps.map(r=>recordingCard(r,true)).join(''):''}${dmNote(l.dmNotes)}${['gray-haven','spit-swallow','glassend','chromehymn','celestial-tunnel','velthros-moon'].includes(id)?contraband('A bookmark in the field notes'):''}</div><aside class="dossier-side"><section class="panel"><p class="eyebrow">Navigation dossier</p><dl><dt>Region</dt><dd>${esc(l.id==='celestial-tunnel'?'Extra-planar · Divine realm':parent?parent.name:rimLabel(l.rim))}</dd>${l.deity?`<dt>Divine patron</dt><dd>${esc(l.deity.name)}<br><small class="muted">${esc(l.deity.domain)}</small></dd>`:''}${l.court?`<dt>Court</dt><dd>${esc(l.court)}</dd>`:''}${l.factions?.length?`<dt>Faction presence</dt><dd>${l.factions.map(esc).join('<br>')}</dd>`:''}${l.visitedBy?`<dt>Flight history</dt><dd>${esc(crewLabel(l.visitedBy))}</dd>`:''}</dl><div class="button-row" style="margin-top:23px">${D.LOCATIONS.some(x=>x.id===id)||id==='maw'?`<a class="button secondary small" href="${path('map',id)}">Locate on star map ↗</a>`:parent?`<a class="button secondary small" href="${path('world',parent.id)}">Parent world ↗</a>`:tag('Uncharted realm')}</div></section>${sessions.length?`<section class="panel"><p class="eyebrow">Related flight logs</p>${sessions.map(s=>`<a class="side-link" href="${path('session',s.num)}">${esc(s.title)}<small>${esc(s.num)}</small></a>`).join('')}</section>`:''}${D.RIMS[l.rim]?`<section class="panel"><p class="eyebrow">${esc(D.RIMS[l.rim].name)}</p><div class="prose" style="font-size:11px">${D.RIMS[l.rim].desc}</div></section>`:''}</aside></div></div>`;}
  function crewPage(){const list=D.CREW.filter(p=>state.crewFilter==='all'||p.status===state.crewFilter);return `<div class="page reveal">${pageHead('People who made it this far','The crew','The living, the lost, and the ones who took another path.',D.CREW.length+' CREW RECORDS')}${tabs([['all','Everyone'],['active','Active crew'],['departed','Departed'],['fallen','Fallen']],'crewFilter',state.crewFilter)}<div class="entity-grid">${list.map(personCard).join('')}</div>${F.originalCrew()}${section('Before the BBC','#journal/c1','Read the original crew’s history ↗')}<div class="notice">The Codex Crew’s history lives in the flight journal, including Ellie, Cro, the Tuning Key, and the events that led to the Shattering.</div></div>`;}
  function personPage(name){const c=D.CREW.find(p=>p.name===name),p=[...allPeople,...(state.dm?D.POI_DM:[])].find(p=>p.name===name),contact=contacts.find(p=>p.name===name);if(!c&&!p)return notFound();const primary=c||p,img=personImage(primary),details=[p,contact].filter((x,i,a)=>x&&a.findIndex(y=>y?.desc===x.desc)===i),relations=D.SESSIONS.filter(s=>plain(s.summary+' '+s.moments.join(' ')).toLowerCase().includes(name.toLowerCase().split(' ')[0])),relatedArt=M.art.filter(a=>!a.video&&!a.source.includes('_alts')&&(a.title.toLowerCase().includes(name.toLowerCase())||a.source.toLowerCase().includes(name.toLowerCase()))).slice(0,12);return `<div class="page reveal"><div class="breadcrumb"><a href="${c?'#crew':'#directory'}">${c?'The crew':'Directory'}</a><span>/</span><span>${esc(name)}</span></div><div class="person-grid"><div>${img?`<button style="padding:0;width:100%" data-art="${esc(img)}" data-caption="${esc(name)}" aria-label="Enlarge portrait of ${esc(name)}">${image(img,name,'person-portrait',true)}</button>`:`<div class="panel no-art" style="height:300px;display:grid;place-items:center;font:80px var(--serif);color:#47687e">${esc(name[0])}</div>`}${c?.altImage?`<details class="alternate-portrait"><summary>${esc(c.altLabel||'Alternate form')}</summary><button data-art="${esc(c.altImage)}" data-caption="${esc(c.altLabel||name)}" style="padding:0;width:100%">${image(c.altImage,c.altLabel||name)}</button></details>`:''}${['Killua','5p0r3','Rook'].includes(name)?contraband():['Yarrow Salt','Zelqua','Rex','Amarante'].includes(name)?contraband('Under the counter'):''}</div><section class="person-details"><p class="eyebrow">${c?'CREW DOSSIER':'CONTACT RECORD'}</p><h1>${esc(name)}</h1><div class="tag-group">${c?.status?tag(c.status,stanceClass(c.status)):''}${p?.stance?tag(p.stance,stanceClass(p.stance)):''}${p?.crew?tag(crewLabel(p.crew)):''}${c?.pronouns?tag(c.pronouns):''}</div>${c?`<div class="panel"><p class="eyebrow">${esc(c.fullName||c.name)}</p><h3>${esc(c.class||'Crew member')}</h3>${c.species?`<p class="muted" style="font-size:11px;margin-bottom:18px">${esc(c.species)}</p>`:''}<div class="prose">${esc(c.tagline)}</div></div>`:''}${details.map(p=>`<div class="panel"><p class="eyebrow">${esc(p.kind||p.faction||'Field record')}</p>${p.role?`<h3 style="font:15px var(--font)">${esc(p.role)}</h3>`:''}<div class="prose">${p.desc||''}</div>${p.location?`<p class="side-link" style="margin-top:15px">${locationLink(p.location)}</p>`:''}${p.faction?`<p class="muted" style="font-size:11px;margin-top:10px">Faction: ${esc(p.faction)}</p>`:''}</div>`).join('')}${relations.length?`<div class="panel"><p class="eyebrow">In the flight journal</p>${relations.map(s=>`<a class="side-link" href="${path('session',s.num)}">${esc(s.title)}<small>${s.num}</small></a>`).join('')}</div>`:''}${relatedArt.length?section('From the art library')+artThumbs(relatedArt):''}${name==='Aelyn Vox'?section('A familiar open frequency')+M.recordings.filter(r=>r.session===11).map(r=>recordingCard(r,true)).join(''):''}</section></div></div>`;}
  function directoryPage(){return `<div class="page reveal">${pageHead('A galaxy of familiar faces','The directory','Contacts, creatures, landmarks, and worlds. Every encounter leaves a record.')}${tabs([['all','All records'],['contacts','Contacts'],['poi','Points of interest'],['places','Places & worlds']],'dirFilter',state.dirFilter)}<div class="toolbar"><input id="directorySearch" type="search" placeholder="Find a person or a place…" aria-label="Filter directory" value="${esc(state.dirSearch)}"><select id="directoryCrew" aria-label="Filter directory by crew"><option value="all">Both crews</option><option value="c2" ${state.dirCrew==='c2'?'selected':''}>H.O.C.2.A</option><option value="c1" ${state.dirCrew==='c1'?'selected':''}>The Codex Crew</option></select><span class="results-count" id="directoryCount"></span></div><div class="entity-grid" id="directoryResults"></div></div>`;}
  function fillDirectory(){let entries=state.dirFilter==='places'?worlds:state.dirFilter==='contacts'?contacts:state.dirFilter==='poi'?[...D.POI,...(state.dm?D.POI_DM:[])]:[...allPeople,...(state.dm?D.POI_DM:[]),...worlds];entries=entries.filter(p=>{const crew=p.crew||p.visitedBy;return (state.dirCrew==='all'||crew==='both'||crew===state.dirCrew)&&plain([p.name,p.kind,p.role,p.desc,p.location?.label,p.subtitle].join(' ')).toLowerCase().includes(state.dirSearch.toLowerCase());});$('directoryCount').textContent=entries.length+' RECORDS';$('directoryResults').innerHTML=entries.length?entries.map(p=>p.id?worldCard(p):personCard(p)).join(''):'<p class="empty">No matching records. Try another name or crew.</p>';}
  function sessionCard(s,full=false){const num=Number(s.num.slice(1)),recap=M.recaps.find(r=>r.session===num),aud=M.recordings.filter(r=>r.session===num),isFull=full;return `<article class="session-card" id="log-${esc(s.num)}"><p class="eyebrow">${esc(s.num)} · ${esc(crewLabel(s.crew))}${recap?' · '+esc(recap.date):aud.length?' · '+esc(aud[0].date):''}</p><h2>${esc(s.title)}</h2><div class="session-place">${locationLink(s.where)}${!s.where?.id&&['S11','S12'].includes(s.num)?` · <a href="${path('world','celestial-tunnel')}">Realm dossier ↗</a>`:''}</div><div class="prose session-summary">${s.summary}</div><ol class="session-moments">${s.moments.map(t=>`<li>${t}</li>`).join('')}</ol>${aud.length?`<div class="section-heading"><h3 style="font:15px var(--serif)">Ghost’s transmissions</h3><a href="#ghost">Full archive ↗</a></div>${aud.map(r=>recordingCard(r,true)).join('')}`:''}${recap?`<details ${isFull?'open':''}><summary>Read the full original written recap</summary><div class="button-row" style="margin-top:18px"><a class="button secondary small" href="${recap.pdf}" target="_blank" rel="noopener">Open original PDF ↗</a></div><div class="prose full-recap">${recap.body}</div></details>`:''}${dmNote(s.dmOnly)}${num===6?contraband('An item left between these pages'):''}${!full?`<div class="button-row" style="margin-top:20px"><a class="button secondary small" href="${path('session',s.num)}">Open session record ↗</a></div>`:''}</article>`;}
  function journalPage(sub){if(sub==='c1')state.journalCrew='c1';const logs=state.journalCrew==='c1'?D.C1_LOG:[...D.SESSIONS].reverse();return `<div class="page reveal">${pageHead('Stories in the wake','The flight journal','Every written log and Ghost recap, together in the order things went spectacularly sideways.',state.journalCrew==='c1'?'THE CODEX CREW':'H.O.C.2.A')}${tabs([['c2','H.O.C.2.A'],['c1','The Codex Crew']],'journalCrew',state.journalCrew)}<div class="journal-layout"><nav class="journal-rail" aria-label="Session index">${logs.map(s=>`<a href="${path('session',s.num)}"><b>${esc(s.num)}</b><span>${esc(s.title)}<small>${esc(s.where?.label||'')}</small></span></a>`).join('')}</nav><div>${logs.map(s=>sessionCard(s)).join('')}</div></div></div>`;}
  function singleSession(id){const logs=[...D.SESSIONS,...D.C1_LOG],s=logs.find(s=>s.num===id);if(!s)return notFound();const i=logs.indexOf(s),next=logs[i+1],prev=logs[i-1];return `<div class="page reveal"><div class="breadcrumb"><a href="${s.crew==='c1'?'#journal/c1':'#journal'}">Flight journal</a><span>/</span><span>${esc(s.num)}</span></div>${sessionCard(s,true)}<div class="button-row" style="justify-content:space-between">${prev?`<a class="button secondary" href="${path('session',prev.num)}">← ${esc(prev.num)} · Previous log</a>`:'<span></span>'}${next?`<a class="button secondary" href="${path('session',next.num)}">${esc(next.num)} · Next log →</a>`:''}</div></div>`;}
  function threadPage(){let hooks=[...D.HOOKS,...(state.dm?D.HOOKS_DM:[])].filter(h=>(state.threadCrew==='all'||h.crew===state.threadCrew||h.crew==='both')&&(state.threadFilter==='all'||(h.kind||'lead')===state.threadFilter));return `<div class="page reveal">${pageHead('Things we have not settled','Open threads','Missions, promises, debts, and questions that followed the crew aboard.',hooks.length+' THREADS')}${tabs([['c2','H.O.C.2.A'],['c1','The Codex Crew'],['all','Both crews']],'threadCrew',state.threadCrew)}${tabs([['all','Every thread'],...Array.from(new Set(D.HOOKS.map(h=>h.kind||'lead'))).map(k=>[k,k.charAt(0).toUpperCase()+k.slice(1)])],'threadFilter',state.threadFilter)}<div class="thread-grid">${hooks.map(h=>`<article id="thread-${encodeURIComponent(h.title)}" class="thread-card ${['high','urgent'].includes(h.urgency)?'high':''}"><div class="tag-group">${tag(h.kind||'lead')}${tag(['high','urgent'].includes(h.urgency)?'High priority':h.urgency||'normal',['high','urgent'].includes(h.urgency)?'red':'')}${h.status?tag(h.status,'gold'):''}${tag(crewLabel(h.crew))}</div><h3>${esc(h.title)}</h3><div class="prose">${h.desc}</div>${h.location?`<div class="thread-location">${locationLink(h.location)}</div>`:''}${h.giver?`<div class="giver">GIVEN BY / ${esc(h.giver)}</div>`:''}</article>`).join('')}</div>${!hooks.length?'<p class="empty">No threads in this category for this crew.</p>':''}</div>`;}
  function lorePage(sub){if(sub==='blue-harvest')return F.blueHarvest();sub=['history','factions','races','heat','regions'].includes(sub)?sub:'history';const loreTabs=[['history','Visual codex'],['factions','Factions'],['races','Peoples'],['heat','Heat & omens'],['regions','The galaxy'],['blue-harvest','Blue Harvest']];let body='';if(sub==='history')body=`<div class="lore-grid">${D.VISUAL_CODEX.map(l=>`<article class="lore-card"><button data-art="images/lore/${l.slug}.png" data-caption="${esc(l.title)}" style="padding:0;width:100%">${image('images/lore/'+l.slug+'.png',l.title)}</button><div class="lore-card-content"><p class="eyebrow">The fractured history</p><h2>${esc(l.title)}</h2><div class="prose">${l.caption}</div></div></article>`).join('')}</div>`;
    if(sub==='factions')body=`<div class="lore-grid">${D.FACTIONS.map(f=>`<article class="panel faction-record" id="faction-${encodeURIComponent(f.name)}">${f.image?`<button data-art="${esc(f.image)}" data-caption="${esc(f.name)}" aria-label="Enlarge ${esc(f.name)} artwork">${image(f.image,f.name)}</button>`:''}<div class="tag-group">${tag(f.stance,stanceClass(f.stance))}</div><h2 style="font-size:23px;margin:15px 0">${esc(f.name)}</h2><div class="prose"><p>${f.blurb}</p><ul>${f.details.map(t=>`<li>${t}</li>`).join('')}</ul>${f.members.length?`<p class="eyebrow" style="margin-top:22px">Known members</p><p>${f.members.map(esc).join(' · ')}</p>`:''}</div></article>`).join('')}</div>`;
    if(sub==='races')body=`<div class="lore-grid">${D.RACES.map(r=>`<article class="lore-card" id="race-${r.slug}"><button data-art="images/races/${r.slug}.${r.slug==='tvaari'?'jpg':'png'}" data-caption="${esc(r.name)}" style="padding:0;width:100%">${image('images/races/'+r.slug+'.'+(r.slug==='tvaari'?'jpg':'png'),r.name)}</button><div class="lore-card-content"><p class="eyebrow">${esc(r.homeworld)} · ${esc(rimLabel(r.rim))}</p><h2>${esc(r.glyph)} ${esc(r.name)}</h2><div class="prose"><p>${r.bio}</p><p>${r.role}</p></div><div class="abilities">${r.abilities.map(t=>`<p>${t}</p>`).join('')}</div><div class="notice" style="margin-top:20px">${r.notes}</div>${r.altImage?`<details class="alternate-portrait"><summary>${esc(r.altLabel||'Alternate form')}</summary><button data-art="${r.altImage}" data-caption="${esc(r.altLabel||r.name)}">${image(r.altImage,r.altLabel||r.name)}</button></details>`:''}</div></article>`).join('')}</div>`;
    if(sub==='heat')body=`<div class="heat-grid">${D.HEAT.map(h=>`<article class="panel heat-card"><p class="eyebrow">${esc(h.category)}</p><div class="heat-heading"><h3>${esc(h.name)}</h3>${tag(h.level||(h.seen?'Observed':'Unseen'),stanceClass(h.level))}</div>${h.clock?`<div class="clock" aria-label="${h.clock.current} of ${h.clock.max} clock segments filled">${Array.from({length:h.clock.max},(_,i)=>`<span class="${i<h.clock.current?'filled':''}"></span>`).join('')}</div>`:''}<div class="prose">${h.desc}</div>${h.trigger?`<div class="heat-trigger">${h.trigger}</div>`:''}</article>`).join('')}</div>`;
    if(sub==='regions')body=`<div class="lore-grid">${Object.entries(D.RIMS).map(([id,r])=>`<article class="panel"><p class="eyebrow">${esc(r.subtitle)}</p><h2 style="font-size:27px;margin:13px 0">${esc(r.name)}</h2><div class="prose">${r.desc}</div><div style="margin-top:20px">${D.LOCATIONS.filter(l=>l.rim===id).map(l=>`<a class="side-link" href="${path('world',l.id)}">${esc(l.name)}<small>${esc(l.subtitle||'')}</small></a>`).join('')}</div></article>`).join('')}<article class="panel"><p class="eyebrow">Beyond the rings</p><h2 style="font-size:27px;margin:13px 0">Stations & the unknown</h2>${worlds.filter(l=>['unknown','station','void'].includes(l.rim)).map(l=>`<a class="side-link" href="${path('world',l.id)}">${esc(l.name)}<small>${esc(l.subtitle||'')}</small></a>`).join('')}</article></div>`;
    return `<div class="page reveal">${pageHead('History is a fragile thing','The codex','The peoples, powers, wounds, and old stories that hold this galaxy together.')}<nav class="tabs" aria-label="Codex sections">${loreTabs.map(([id,label])=>`<a class="tab${id===sub?' active':''}" href="#lore/${id}" ${id===sub?'aria-current="page"':''}>${esc(label)}</a>`).join('')}</nav>${body}</div>`;
  }
  function ghostPage(){return `<div class="page reveal"><section class="ghost-hero"><div class="ghost-hero-copy"><p class="eyebrow"><span class="status-dot"></span> GHOST-17X · OPEN FREQUENCY</p><h1>Somebody left<br>the comms open.</h1><div class="prose">Every voice recap, rant, and stray transmission in one place. Original recordings, questionable narration, absolutely no editorial restraint.</div><div class="button-row"><button class="button" data-play="s15">▶ Play the latest recap</button><a class="button secondary" href="#journal">Written flight logs ↗</a></div></div><div class="ghost-hero-image">${image(asset(4),'Aelyn and GHOST-17X','',true)}<span>TRANSMISSION ARCHIVE / ${M.recordings.length} RECORDINGS</span></div></section>${tabs([['all','All transmissions'],['recap','Session recaps'],['rant','Rants'],['line','Voice lines']],'ghostFilter',state.ghostFilter)}<div class="toolbar"><span class="eyebrow" style="color:#7091a5">Tune the archive</span><select id="ghostSession" aria-label="Filter Ghost archive by session"><option value="all">Every session</option>${[...new Set(recordings.map(r=>r.session))].map(s=>`<option value="${s}" ${String(s)===state.ghostSession?'selected':''}>Session ${s}</option>`).join('')}</select><span class="results-count" id="ghostCount"></span></div><div class="recording-list" id="ghostRecords"></div><p class="ghost-note">Session 11’s standalone lines belong to “A Day With Doc,” August 2, 2026. Their individual scenes have not been specified. Ghost calls Rook “Brook” in his Session 15 narration; her campaign name is Rook.</p>${contraband('Something wedged behind the comms panel')}</div>`;}
  function fillGhost(){const list=recordings.filter(r=>(state.ghostFilter==='all'||r.kind===state.ghostFilter)&&(state.ghostSession==='all'||String(r.session)===state.ghostSession));$('ghostCount').textContent=list.length+' TRANSMISSIONS';$('ghostRecords').innerHTML=list.length?list.map(r=>recordingCard(r)).join(''):'<p class="empty">No transmissions on this frequency yet.</p>';if(list.length)state.queue=list.map(r=>r.id);syncPlayer();}
  function artPage(){const cats=[...new Set(M.art.map(a=>a.category))];return `<div class="page reveal">${pageHead('Scenes, faces, and fragments','The art library','The campaign’s collected artwork and moving images. Open any piece for a closer look.',M.art.length+' LIBRARY ASSETS')}<div class="toolbar"><input type="search" id="artSearch" placeholder="Search artwork, a character, or a place…" value="${esc(state.artSearch)}" aria-label="Search artwork"><select id="artCategory" aria-label="Filter artwork category"><option value="all">Every collection</option>${cats.map(c=>`<option value="${esc(c)}" ${c===state.artFilter?'selected':''}>${esc(c.replace(/^\d+ /,''))}</option>`).join('')}<option value="legacy" ${state.artFilter==='legacy'?'selected':''}>Original illustrations</option><option value="video" ${state.artFilter==='video'?'selected':''}>Moving images</option></select><span class="results-count" id="artCount"></span></div><div class="gallery-grid" id="artResults"></div><button class="button secondary load-more" id="artMore" hidden>Load more artwork</button></div>`;}
  function fillArt(){const input=state.artSearch.toLowerCase(),source=state.artFilter==='legacy'?(window.LEGACY_ART||[]):M.art;const list=source.filter(a=>(['all','legacy'].includes(state.artFilter)||state.artFilter==='video'&&a.video||a.category===state.artFilter)&&[a.title,a.category,a.source].join(' ').toLowerCase().includes(input));$('artCount').textContent=list.length+' ASSETS';$('artResults').innerHTML=list.length?list.slice(0,state.artLimit).map(a=>{const poster=a.video?M.art.find(p=>!p.video&&p.id===a.id)?.src:a.src;return `<button class="gallery-card" data-art="${esc(a.src)}" data-video="${a.video?'true':'false'}" data-caption="${esc(a.title)}">${poster?image(poster,a.title):'<span class="video-preview" aria-hidden="true">▷</span>'}${a.video?'<span class="video-badge">▷ VIDEO</span>':''}<span class="gallery-caption"><strong>${esc(a.title)}</strong><small>${esc(a.video?'MOVING IMAGE':'FIELD IMAGE')} / ${esc(a.id||'ARCHIVE')}</small><span class="gallery-category">${esc(a.category.replace(/^\d+ /,''))}</span></span></button>`;}).join(''):'<p class="empty">No artwork matches this search.</p>';$('artMore').hidden=list.length<=state.artLimit;}
  function notFound(){return `<div class="page">${pageHead('A gap in the archive','Signal not found','That record has not been logged. Search the archive or return to the bridge.')}<a class="button" href="#bridge">Return to bridge ↗</a></div>`;}
  function scatterPaperbacks(){
    const stash=(target,variant='')=>{if(!target||target.querySelector('.paperback-stash'))return;target.classList.add('with-paperback');target.insertAdjacentHTML('beforeend',tuckedBook(variant));};
    stash(document.querySelector('.sidebar-bottom'),'spine');
    stash(document.querySelector('.site-footer'),'peek');
    if(state.route==='bridge'){stash(document.querySelector('.bridge-hero'),'hero-book');stash(document.querySelector('.quote-panel'),'peek');}
    if(state.route==='world'&&['oratoria','nocturna-i','aurelia','echo','rathun','leztos','akora','edgewatch-9','port-vesper','harthgrove','nocturne-13','maw'].includes(state.sub))stash(document.querySelector('.dossier-hero'),'hero-book');
    if(state.route==='person'&&['Lor','Aelyn Vox','Flint D. McCoy','Bix','Nibs','Pip','Mother Sunder',"Kah'ryn",'Vale','Bragg Mentan','Cro'].includes(state.sub))stash(document.querySelector('.person-details .panel'),'peek');
    if(state.route==='crew')stash(document.querySelector('.notice'),'peek');
    if(state.route==='session'&&['S1','S7','S11','S13','S15','C1'].includes(state.sub))stash(document.querySelector('.session-card'));
    if(state.route==='journal')document.querySelectorAll('.session-card').forEach((el,i)=>{if([2,5,9,13].includes(i))stash(el,i%2?'peek':'');});
    if(state.route==='lore')document.querySelectorAll('.lore-card,.lore-grid>.panel,.heat-card').forEach((el,i)=>{if(i%3===1)stash(el,i%2?'peek':'');});
    if(state.route==='ghost')stash(document.querySelector('.ghost-hero-copy'),'hero-book');
    if(state.route==='directory'||state.route==='art')stash(document.querySelector('.page-head'),'spine');
    if(state.route==='threads')document.querySelectorAll('.thread-card').forEach((el,i)=>{if([1,4,8].includes(i))stash(el,'peek');});
  }
  function readRoute(){const hash=location.hash.slice(1)||'bridge';let [route,...rest]=hash.split('/'),sub;try{sub=decodeURIComponent(rest.join('/'));}catch{sub='';}if(world(route)){sub=route;route='world';}if(route==='journey')route='journal';if(route==='contacts'||route==='poi'){state.dirFilter=route;route='directory';}if(route==='factions'||route==='races'||route==='heat'){sub=route;route='lore';}if(route==='visualcodex'){route='lore';sub='history';}return{route,sub};}
  function render(){const prev=state.route;state.galaxy?.destroy();state.galaxy=null;const r=readRoute();state.route=r.route;state.sub=r.sub;if(r.route==='threads'&&r.sub){state.threadCrew='all';state.threadFilter='all';}const renderers={bridge,previously:()=>F.previously(r.sub),relationships:()=>F.relationships(r.sub),map:mapPage,world:()=>worldPage(r.sub),crew:crewPage,person:()=>personPage(r.sub),directory:directoryPage,journal:()=>journalPage(r.sub),session:()=>singleSession(r.sub),threads:threadPage,lore:()=>lorePage(r.sub.split('/')[0]),ghost:ghostPage,art:artPage};$('main').innerHTML=(renderers[r.route]||notFound)();const navRoute=r.route==='world'?'map':r.route==='person'?(D.CREW.some(c=>c.name===r.sub)?'crew':'directory'):r.route==='session'?'journal':r.route;$('primaryNav').innerHTML=navItems.map(([id,label])=>`<a class="nav-link${id===navRoute?' active':''}" href="#${id}" ${id===navRoute?'aria-current="page"':''}>${icon(id)}<span>${label}</span>${id==='ghost'?`<span class="nav-count">${M.recordings.length}</span>`:''}</a>`).join('');const title=r.route==='world'?world(r.sub)?.name:r.route==='person'?r.sub:r.route==='session'?r.sub:navItems.find(n=>n[0]===navRoute)?.[1];$('viewLabel').textContent=title||'Archive';document.title=(title?title+' · ':'')+'The Shattering';$('sidebar').classList.remove('open');$('menuToggle').setAttribute('aria-expanded','false');if(r.route==='map'){mountMap();if(r.sub)state.galaxy.focus(r.sub);}if(r.route==='directory')fillDirectory();if(r.route==='ghost')fillGhost();if(r.route==='art')fillArt();syncPlayer();buildSearchIndex();scatterPaperbacks();window.scrollTo({top:0,behavior:'instant'});if(r.route==='lore'&&r.sub.includes('/')){const [section,...name]=r.sub.split('/');$(section==='races'?'race-'+name.join('/'):'faction-'+encodeURIComponent(name.join('/')))?.scrollIntoView({block:'start',behavior:'instant'});}if(r.route==='threads'&&r.sub)$('thread-'+encodeURIComponent(r.sub))?.scrollIntoView({block:'start',behavior:'instant'});if(prev!==r.route||document.activeElement?.closest('main'))$('main').focus({preventScroll:true});}
  // A single audio element survives navigation. All cards control this same player.
  const audio=$('ghostAudio');audio.volume=.8;
  async function play(id,seek){const r=M.recordings.find(r=>r.id===id);if(!r)return;if(state.playingId===id&&seek===undefined){if(audio.paused)await resume();else audio.pause();return;}if(state.playingId!==id){audio.pause();state.playingId=id;audio.src=r.src;audio.load();}if(seek!==undefined){if(audio.readyState)audio.currentTime=Math.max(0,Math.min(seek,audio.duration||W[id]?.duration||0));else audio.addEventListener('loadedmetadata',()=>{if(state.playingId===id)audio.currentTime=Math.min(seek,audio.duration);},{once:true});}$('persistentPlayer').hidden=false;document.body.classList.add('player-open');$('playerTitle').textContent=r.title;await resume();}
  async function resume(){try{await audio.play();}catch(error){if(error.name!=='AbortError')toast('Playback could not start. Tap Play to retry.');}syncPlayer();}
  function syncPlayer(){const paused=audio.paused;$('playerToggle').textContent=paused?'▶':'Ⅱ';$('playerToggle').setAttribute('aria-label',paused?'Play recording':'Pause recording');document.querySelectorAll('[data-recording]').forEach(el=>{const selected=el.dataset.recording===state.playingId;el.classList.toggle('playing',selected);const b=el.querySelector('[data-play]'),r=M.recordings.find(r=>r.id===el.dataset.recording);b.textContent=selected&&!paused?'Ⅱ':'▶';b.setAttribute('aria-label',(selected&&!paused?'Pause ':'Play ')+(r?.title||''));});updateProgress();}
  function updateProgress(){const d=Number.isFinite(audio.duration)?audio.duration:W[state.playingId]?.duration||0,p=d?audio.currentTime/d:0;$('playerSeek').value=p*100;$('playerTime').textContent=formatTime(audio.currentTime)+' / '+formatTime(d);document.querySelectorAll('.recording.playing [data-peak]').forEach(r=>r.classList.toggle('elapsed',Number(r.dataset.peak)<=p));}
  function queueStep(direction,automatic=false){const q=state.queue.includes(state.playingId)?state.queue:recordings.map(r=>r.id),index=q.indexOf(state.playingId),next=index+direction;if(automatic&&next>=q.length){syncPlayer();return;}play(q[(next+q.length)%q.length]);}
  audio.addEventListener('timeupdate',updateProgress);audio.addEventListener('loadedmetadata',updateProgress);audio.addEventListener('play',syncPlayer);audio.addEventListener('pause',syncPlayer);audio.addEventListener('ended',()=>queueStep(1,true));audio.addEventListener('error',()=>{toast('This transmission could not be loaded. Try Play again.');syncPlayer();});
  $('playerToggle').addEventListener('click',()=>state.playingId&&play(state.playingId));$('playerPrevious').addEventListener('click',()=>queueStep(-1));$('playerNext').addEventListener('click',()=>queueStep(1));$('playerSeek').addEventListener('input',e=>{if(Number.isFinite(audio.duration))audio.currentTime=audio.duration*Number(e.target.value)/100;});$('playerVolume').addEventListener('input',e=>audio.volume=Number(e.target.value));$('playerClose').addEventListener('click',()=>{audio.pause();$('persistentPlayer').hidden=true;document.body.classList.remove('player-open');});$('playerPortrait').src=asset(4);
  function openArt(src,caption='',video=false){state.lastFocus=document.activeElement;$('lightboxMedia').innerHTML=video?`<video controls autoplay playsinline preload="metadata" aria-label="${esc(caption)}"><source src="${esc(src)}" type="video/mp4"></video>`:image(src,caption,'',true);if(video)audio.pause();$('lightboxCaption').textContent=caption;$('lightbox').showModal();}
  function closeDialog(id){$(id).close();if(id==='lightbox'){$('lightbox').querySelector('video')?.pause();$('lightboxMedia').replaceChildren();}state.lastFocus?.focus?.();}
  function toast(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>$('toast').hidden=true,4000);}
  function setMotion(value){state.motion=value;safeWrite('shattering-motion',value?'on':'off');document.body.classList.toggle('motion-off',!value);$('motionToggle').setAttribute('aria-pressed',String(value));$('motionState').textContent=value?'Motion on':'Motion off';state.galaxy?.setMotion(value);}
  $('motionToggle').addEventListener('click',()=>setMotion(!state.motion));reduced.addEventListener('change',e=>{if(e.matches)setMotion(false);});setMotion(state.motion);
  $('dmToggle').addEventListener('click',()=>{if(state.dm){state.dm=false;$('dmToggle').setAttribute('aria-pressed','false');render();toast('DM notes hidden.');}else{state.lastFocus=document.activeElement;$('dmError').textContent='';$('dmPassword').value='';$('dmDialog').showModal();$('dmPassword').focus();}});
  $('dmForm').addEventListener('submit',e=>{e.preventDefault();if($('dmPassword').value==='rosco'){state.dm=true;$('dmToggle').setAttribute('aria-pressed','true');$('dmDialog').close();render();toast('DM notes are visible.');}else $('dmError').textContent='That password did not match.';});
  $('menuToggle').addEventListener('click',()=>{$('sidebar').classList.toggle('open');$('menuToggle').setAttribute('aria-expanded',String($('sidebar').classList.contains('open')));});
  let searchCorpus=[];
  function buildSearchIndex(){searchCorpus=[...F.searchable,...worlds.map(l=>({title:l.name,type:l.id==='celestial-tunnel'?'Plane':l.parent?'Landmark':'World',context:l.id==='celestial-tunnel'?'Divine realm · Plane of existence · A Day With Doc':l.subtitle||world(l.parent)?.name||rimLabel(l.rim),text:l.desc,url:path('world',l.id),image:l.image})),...D.CREW.map(p=>({title:p.name,type:'Crew',context:p.class,text:p.tagline,url:path('person',p.name),image:p.image})),...[...allPeople,...(state.dm?D.POI_DM:[])].map(p=>({title:p.name,type:'Contact',context:p.kind||p.role,text:p.desc,url:path('person',p.name),image:personImage(p)})),...[...D.SESSIONS,...D.C1_LOG].map(s=>({title:s.num+' · '+s.title,type:'Flight log',context:s.where?.label,text:s.summary+' '+s.moments.join(' '),url:path('session',s.num)})),...D.FACTIONS.map(f=>({title:f.name,type:'Faction',context:f.stance,text:f.blurb,url:path('lore','factions')+'/'+encodeURIComponent(f.name)})),...D.RACES.map(r=>({title:r.name,type:'People',context:r.homeworld,text:r.bio,url:path('lore','races')+'/'+r.slug})),...D.HOOKS.map(h=>({title:h.title,type:'Thread',context:h.location?.label,text:h.desc,url:path('threads',h.title)})),...recordings.map(r=>({title:r.title,type:'Transmission',context:r.date,text:r.setting,url:'#ghost',recording:r.id,image:asset(4)}))].map(r=>({...r,haystack:plain([r.title,r.context,r.text].join(' ')).toLowerCase()}));}
  function openSearch(){state.lastFocus=document.activeElement;$('searchDialog').showModal();$('globalSearch').value='';state.searchIndex=0;fillSearch();$('globalSearch').focus();}
  function fillSearch(){const q=$('globalSearch').value.toLowerCase().trim(),terms=q.split(/\s+/).filter(Boolean);let list=q?searchCorpus.filter(r=>terms.every(t=>r.haystack.includes(t))).sort((a,b)=>Number(b.title.toLowerCase().includes(q))-Number(a.title.toLowerCase().includes(q))):searchCorpus.filter(r=>['Straleon','Rook','The Celestial Tunnel · A Day With Doc','S15 · Defectors and Discounts'].includes(r.title));list=list.filter((r,i,a)=>a.findIndex(x=>x.url===r.url&&x.title===r.title&&x.type===r.type)===i).slice(0,30);state.searchResults=list;state.searchIndex=Math.min(state.searchIndex,Math.max(0,list.length-1));$('searchResults').innerHTML=list.length?list.map((r,i)=>`<button class="search-result${i===state.searchIndex?' active':''}" role="option" aria-selected="${i===state.searchIndex}" data-search-index="${i}">${r.image?image(r.image,r.title):'<span class="result-symbol" aria-hidden="true">✧</span>'}<span><strong>${esc(r.title)}</strong><small>${esc(short(r.context||r.text,85))}</small></span><span class="result-type">${esc(r.type)}</span></button>`).join(''):'<p class="empty">No records found. Try a different name.</p>';}
  function chooseSearch(index){const r=state.searchResults[index];if(!r)return;$('searchDialog').close();if(location.hash===r.url)render();else location.hash=r.url;if(r.recording)play(r.recording);}
  $('openSearch').addEventListener('click',openSearch);$('globalSearch').addEventListener('input',()=>{state.searchIndex=0;fillSearch();});$('globalSearch').addEventListener('keydown',e=>{if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();state.searchIndex=Math.max(0,Math.min(state.searchResults.length-1,state.searchIndex+(e.key==='ArrowDown'?1:-1)));fillSearch();$('searchResults').querySelector('.active')?.scrollIntoView({block:'nearest'});}if(e.key==='Enter'){e.preventDefault();chooseSearch(state.searchIndex);}});
  document.addEventListener('click',e=>{const button=e.target.closest('button,a');if(!button)return;if(button.dataset.nav){location.hash=button.dataset.nav;return;}if(button.dataset.close){closeDialog(button.dataset.close);return;}if(button.hasAttribute('data-book')){e.preventDefault();openArt('media/art/blue-harvest.webp','Sorrow Yalt sends his regards.');return;}if(button.dataset.art){openArt(button.dataset.art,button.dataset.caption,button.dataset.video==='true');return;}if(button.dataset.play){play(button.dataset.play);return;}if(button.dataset.wave){const rect=button.getBoundingClientRect(),ratio=Math.max(0,Math.min(1,(e.clientX-rect.left)/rect.width));play(button.dataset.wave,ratio*(W[button.dataset.wave]?.duration||0));return;}if(button.dataset.searchIndex!==undefined){chooseSearch(Number(button.dataset.searchIndex));return;}if(button.dataset.filter){state[button.dataset.filter]=button.dataset.value;render();return;}if(button.dataset.map){const action=button.dataset.map,g=state.galaxy;if(action==='index'){state.dirFilter='places';location.hash='#directory';return;}if(!g)return;if(action==='frame'&&g.selected)g.focus(g.selected);if(action==='in')g.changeZoom(1.3);if(action==='out')g.changeZoom(.77);if(action==='reset')g.reset();if(action==='close'){g.selected=null;g.options.onSelect(null);g.draw();}if(action==='chart'||action==='cinematic'){g.setChart(action==='chart');document.querySelectorAll('[data-map="chart"],[data-map="cinematic"]').forEach(b=>{b.classList.toggle('active',b.dataset.map===action);b.setAttribute('aria-pressed',String(b.dataset.map===action));});}if(action==='filter'){g.setFilter(g.filter==='all'?'visited':'all');button.classList.toggle('active',g.filter==='visited');button.setAttribute('aria-pressed',String(g.filter==='visited'));}}if(button.id==='artMore'){state.artLimit+=48;fillArt();}});
  document.addEventListener('input',e=>{if(e.target.id==='flightSlider')updateFlight(Number(e.target.value));if(e.target.id==='directorySearch'){state.dirSearch=e.target.value;fillDirectory();}if(e.target.id==='artSearch'){state.artSearch=e.target.value;state.artLimit=48;fillArt();}});
  document.addEventListener('change',e=>{if(e.target.id==='connectionFocus'){location.hash=path('relationships',e.target.value);}if(e.target.id==='directoryCrew'){state.dirCrew=e.target.value;fillDirectory();}if(e.target.id==='ghostSession'){state.ghostSession=e.target.value;fillGhost();}if(e.target.id==='artCategory'){state.artFilter=e.target.value;state.artLimit=48;fillArt();}});
  for(const id of ['searchDialog','lightbox','dmDialog']){$(id).addEventListener('click',e=>{if(e.target===$(id)){const r=$(id).getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog(id);}});$(id).addEventListener('close',()=>{if(id==='lightbox'){$('lightbox').querySelector('video')?.pause();$('lightboxMedia').replaceChildren();}state.lastFocus?.focus?.();});}
  let secretKeys='';document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('searchDialog').open?closeDialog('searchDialog'):openSearch();}if(e.key==='Escape'){const dialog=[...document.querySelectorAll('dialog[open]')].at(-1);if(dialog){e.preventDefault();closeDialog(dialog.id);return;}$('sidebar').classList.remove('open');$('menuToggle').setAttribute('aria-expanded','false');}if(e.target.matches('input,textarea,select')||e.ctrlKey||e.metaKey)return;if(e.key.length===1){secretKeys=(secretKeys+e.key.toLowerCase()).slice(-11);if(secretKeys.endsWith('blueharvest')&&!$('lightbox').open)openArt('media/art/blue-harvest.webp','A magical blue hog is a heavy burden.');}});
  document.addEventListener('dblclick',e=>{if(e.target.closest('.wordmark,.ship-mark,.hero-coordinates,.flight-number'))openArt('media/art/blue-harvest.webp','Four arms. One vow.');});
  window.addEventListener('hashchange',render);render();
})();
